  $owner: String!
  $repo: String!
) {
  repository(owner: $owner, name: $repo) {
    ...RepositoryPickerRepository
    id
  }
  viewer {
    ...RepositoryPickerTopRepositories
    id
  }
}

fragment RepositoryPickerRepository on Repository {
  id
