}

fragment RepositoryPickerTopRepositories on User {
  topRepositories(first: 10, hasIssuesEnabled: true, orderBy: {field: UPDATED_AT, direction: DESC}) {
    edges {
      node {
        ...RepositoryPickerRepository
        id
      }
    }
  }
}

210b13c5e8f3e0494ec05c008d0e0e0f.query:
query ParticipantsListQuery(
  $repo: String!
  $owner: String!
  $number: Int!
) {
  repository(name: $repo, owner: $owner) {
    issue(number: $number) {
      participants(first: 100) {
        nodes {
          avatarUrl(size: 64)
          login
          name
          id
        }
      }
      id
    }
    id
  }
}

